import{_ as e,o as r,c as t,a2 as l}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Общая планета и поселения","description":"","frontmatter":{"pageId":"players/world","contentRevision":1},"headers":[],"relativePath":"ru/players/world.md","filePath":"ru/players/world.md"}'),i={name:"ru/players/world.md"};function o(s,a,d,n,p,h){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="общая-планета-и-поселения" tabindex="-1">Общая планета и поселения <a class="header-anchor" href="#общая-планета-и-поселения" aria-label="Permalink to &quot;Общая планета и поселения&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Все игроки используют планету сервера. Выбирай свободную клетку при создании колонии. На карте чужие поселения показывают владельца, присутствие, давность посещения, возраст колонии и диапазон богатства, если эти данные доступны.</p><p>Караван и транспортные капсулы предлагают действия на чужом поселении: передача, рейд, визит или live — в зависимости от режима, доступности хозяина и правил сервера. Проверяй подпись действия до подтверждения: визит и реальный рейд не взаимозаменяемы.</p><p>Цветной слой гильдий включается отдельно и не заменяет обычные маркеры карты.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>По умолчанию одно поселение на игрока. Офлайн-маркер не означает, что карта продолжает симулироваться. Не все действия доступны в мирном режиме.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./visits">Визиты и магазин</a></li><li><a href="./raids-incidents">Рейды и платные события</a></li><li><a href="./guild-influence">Влияние гильдий</a></li></ul>',10)])])}const _=e(i,[["render",o]]);export{u as __pageData,_ as default};
